// Launch Radar · Static Dashboard Application (dashboard/app.js)
// Reads window.RADAR (generated by main.ts from /input/snapshot.json), renders the 758-protocol
// parity strip, held-out backtest cards (LOO, Walk-Forward, Brier score), filterable & sortable
// pre-token board, live-token benchmark table, category peer-multiple audit, and side-by-side
// protocol inspector with live arithmetic verification and costed 6-step farm plans.
(function () {
  'use strict';

  var DATA = window.RADAR;
  if (!DATA) return;
  var app = document.getElementById('board');
  var state = {
    q: '',
    category: 'all',
    chain: 'all',
    tier: 'all',
    tab: 'pre-token',
    sort: 'implied',
    dir: -1,
    selected: null
  };

  var usdFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmtUsd(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    if (Math.abs(n) >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
    if (Math.abs(n) >= 1e6) return '$' + (n / 1e6).toFixed(1) + 'M';
    if (Math.abs(n) >= 1e3) return '$' + Math.round(n / 1e3) + 'K';
    return usdFmt.format(n);
  }
  function fmtPct(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    return (n > 0 ? '+' : '') + n.toFixed(2) + '%';
  }
  function fmtAge(days) {
    if (days === null || days === undefined) return '365d (est)';
    if (days >= 365) return (days / 365).toFixed(1) + 'y (' + days + 'd)';
    return Math.max(0, Math.round(days)) + 'd';
  }
  function fmtAgeShort(days) {
    if (days === null || days === undefined) return '1.0y*';
    if (days >= 365) return (days / 365).toFixed(1) + 'y';
    return Math.max(0, Math.round(days)) + 'd';
  }

  // Exact in-page recomputation of lib/model.ts impliedValue() to prove code-data parity
  function impliedOf(row, model) {
    var rawG = row.change_7d === null || row.change_7d === undefined ? 0 : row.change_7d;
    var growth = Math.min(model.growth_cap, Math.max(model.growth_floor, rawG));
    var growthMult = 1 + (growth / 100) * model.growth_weight;
    var age = row.age_days === null || row.age_days === undefined ? model.unknown_age_days : row.age_days;
    var maturity = model.maturity_floor + (Math.min(Math.max(age, 0), model.maturity_days) / model.maturity_days) * model.maturity_range;
    var chainCount = Math.max(1, row.chains ? row.chains.length : 1);
    var chainMult = 1 + Math.min(Math.log2(chainCount), 3) * model.chain_weight;
    var cat = row.category || 'Other';
    var catMult = model.category_multipliers && model.category_multipliers[cat] !== undefined ? model.category_multipliers[cat] : 1.0;
    var ratio = Math.max(1e-4, row.tvl_usd / model.ref_tvl_usd);
    var tvlScale = Math.pow(ratio, model.beta_tvl - 1);
    var base = row.tvl_usd * model.base_multiple * tvlScale * catMult;
    return Math.max(1, Math.round(base * growthMult * maturity * chainMult));
  }

  // Exact in-page derivation of lib/model.ts farmSteps()
  function chainOf(p) { return p.chains && p.chains.length > 0 ? p.chains[0] : 'Ethereum'; }
  function chainGasUsd(chain) {
    var c = chain.toLowerCase();
    if (c === 'ethereum' || c === 'bitcoin') return 4.5;
    if (c === 'tron' || c === 'bittensor') return 1.5;
    return 0.35;
  }
  function actionFor(p, capital, chain) {
    var c = (p.category || '').toLowerCase();
    var name = p.name;
    if (c.indexOf('curator') >= 0 || c.indexOf('allocator') >= 0) {
      return 'Deposit $' + capital + ' of USDC or WETH into ' + name + "'s highest-utilization curated vault on " + chain + ' and hold the receipt shares.';
    }
    if (c.indexOf('lend') >= 0 || c.indexOf('cdp') >= 0 || c.indexOf('collateral') >= 0) {
      return 'Supply $' + capital + ' of collateral to ' + name + ' on ' + chain + ' and borrow 30% against it to register active lending and borrowing volume.';
    }
    if (c.indexOf('dex') >= 0 || c.indexOf('yield') >= 0 || c.indexOf('farm') >= 0 || c.indexOf('liquidity') >= 0) {
      return 'Provide $' + capital + ' of two-sided liquidity into ' + name + "'s primary active pool on " + chain + ' and stake the LP receipt.';
    }
    if (c.indexOf('rwa') >= 0 || c.indexOf('basis') >= 0 || c.indexOf('stable') >= 0) {
      return 'Mint or subscribe $' + capital + ' into ' + name + "'s yield-bearing asset on " + chain + ' and hold it in self-custody for snapshot accrual.';
    }
    if (c.indexOf('perpetual') >= 0 || c.indexOf('derivative') >= 0 || c.indexOf('option') >= 0 || c.indexOf('prediction') >= 0) {
      return 'Deposit $' + capital + ' of USDC margin on ' + name + ' (' + chain + ') and execute two delta-neutral hedges to log organic notional volume.';
    }
    if (c.indexOf('bridge') >= 0 || c.indexOf('cross chain') >= 0) {
      return 'Bridge $' + capital + ' of USDC to ' + chain + ' via ' + name + ' across at least two distinct source chains and utilize the destination liquidity.';
    }
    if (c.indexOf('staking') >= 0 || c.indexOf('restak') >= 0) {
      return 'Stake $' + capital + ' of native collateral through ' + name + ' on ' + chain + ' and keep the liquid receipt active in a secondary DeFi market.';
    }
    return 'Deposit $' + capital + ' of USDC into ' + name + "'s core contract on " + chain + ' and keep the position active across weekly epoch snapshots.';
  }
  function farmStepsFor(p) {
    var chain = chainOf(p);
    var secChain = p.chains && p.chains.length > 1 ? p.chains[1] : null;
    var summary = p.farm_summary || { recommended_capital_usd: 150, est_total_gas_usd: 12, hold_days: 30, est_apr_equiv_pct: 24, net_ev_usd: 18 };
    var capital = summary.recommended_capital_usd;
    var hold = summary.hold_days;
    var txGas = chainGasUsd(chain);
    var setupGas = Math.max(1, Math.round(txGas * 2));
    var weeklyGas = Math.max(1, Math.round(txGas));
    var tvlM = Math.round(p.tvl_usd / 1e6);
    return [
      {
        text: 'Provision a dedicated non-sybil wallet on ' + chain + ' funded from a clean exchange withdrawal with at least 0.02 native gas reserve.',
        cost: '~$' + Math.max(1, Math.round(txGas)) + ' network funding fee',
        time: '5 minutes'
      },
      {
        text: actionFor(p, capital, chain),
        cost: '$' + capital + ' principal locked + ~$' + setupGas + ' approval and deposit gas on ' + chain,
        time: '15 minutes setup'
      },
      {
        text: secChain
          ? 'Execute one recurring interaction per week on ' + chain + ' and bridge a $' + Math.round(capital * 0.25) + ' tranche to ' + secChain + ' for multi-chain multiplier eligibility.'
          : 'Execute one organic weekly transaction (rebalance, reward compound, or parameter vote) on ' + chain + ' across distinct calendar weeks.',
        cost: '~$' + weeklyGas + '/week in ' + chain + ' gas (~$' + summary.est_total_gas_usd + ' total campaign gas)',
        time: '10 minutes weekly'
      },
      {
        text: 'Maintain time-weighted average balance for at least ' + hold + ' days (protocol TVL $' + tvlM + 'M dilution tier; target net EV $' + summary.net_ev_usd + ' at ' + summary.est_apr_equiv_pct + '% equiv APR).',
        cost: '$' + capital + ' opportunity cost (~$' + Math.max(1, Math.round(capital * 0.05 * (hold / 365))) + ' at 5% base risk-free yield)',
        time: hold + ' days continuous hold'
      },
      {
        text: 'Verify epoch points or retroactive snapshot inclusion via ' + p.name + "'s official dashboard and revoke idle token approvals after snapshot lock.",
        cost: '$0 verification ($1 approval revoke gas, never pay third-party claim fees)',
        time: '10 minutes audit'
      },
      {
        text: 'Log wallet address, entry tx hashes, and unlock date in your farm ledger to unwind principal cleanly once TGE distribution settles.',
        cost: '$0 ledger tracking',
        time: '5 minutes'
      }
    ];
  }

  function el(tag, attrs) {
    var node = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (k === 'class') node.className = attrs[k];
        else if (k === 'text') node.textContent = attrs[k];
        else if (k.slice(0, 2) === 'on') node.addEventListener(k.slice(2), attrs[k]);
        else if (attrs[k] !== null && attrs[k] !== undefined) node.setAttribute(k, attrs[k]);
      });
    }
    for (var i = 2; i < arguments.length; i++) {
      var child = arguments[i];
      if (child === null || child === undefined) continue;
      if (Array.isArray(child)) child.forEach(function (c) { if (c) node.appendChild(c); });
      else if (typeof child === 'string') node.appendChild(document.createTextNode(child));
      else node.appendChild(child);
    }
    return node;
  }

  function readHash() {
    var hash = window.location.hash.replace(/^#/, '');
    if (!hash) return;
    var params = new URLSearchParams(hash);
    if (params.get('q')) state.q = params.get('q');
    if (params.get('p')) state.selected = params.get('p');
    if (params.get('category')) state.category = params.get('category');
    if (params.get('chain')) state.chain = params.get('chain');
    if (params.get('tier')) state.tier = params.get('tier');
    if (params.get('tab')) state.tab = params.get('tab');
  }
  function writeHash() {
    var params = new URLSearchParams();
    if (state.q) params.set('q', state.q);
    if (state.category !== 'all') params.set('category', state.category);
    if (state.chain !== 'all') params.set('chain', state.chain);
    if (state.tier !== 'all') params.set('tier', state.tier);
    if (state.tab !== 'pre-token') params.set('tab', state.tab);
    if (state.selected) params.set('p', state.selected);
    var next = params.toString();
    if (next) window.history.replaceState(null, '', '#' + next);
    else window.history.replaceState(null, '', window.location.pathname + window.location.search);
  }

  function filteredRows() {
    var q = state.q.trim().toLowerCase();
    return DATA.rows.filter(function (r) {
      if (state.category !== 'all' && (r.category || 'Other') !== state.category) return false;
      if (state.chain !== 'all' && (!r.chains || r.chains.indexOf(state.chain) < 0)) return false;
      if (state.tier === 'watchlist' && !r.on_watchlist) return false;
      if (state.tier === 'early' && r.on_watchlist) return false;
      if (!q) return true;
      var hay = [r.name, r.slug, r.category, (r.chains || []).join(' '), r.farm_summary ? r.farm_summary.verdict : ''].join(' ').toLowerCase();
      return hay.indexOf(q) >= 0;
    });
  }

  function sortedRows(list) {
    var key = state.sort;
    return list.slice().sort(function (a, b) {
      var av, bv;
      if (key === 'name') { av = a.name.toLowerCase(); bv = b.name.toLowerCase(); }
      else if (key === 'tvl') { av = a.tvl_usd; bv = b.tvl_usd; }
      else if (key === 'growth') { av = a.change_7d === null ? -Infinity : a.change_7d; bv = b.change_7d === null ? -Infinity : b.change_7d; }
      else if (key === 'age') { av = a.age_days === null ? 365 : a.age_days; bv = b.age_days === null ? 365 : b.age_days; }
      else if (key === 'odds') { av = a.token_odds_pct || 0; bv = b.token_odds_pct || 0; }
      else if (key === 'ev') { av = a.farm_summary ? a.farm_summary.net_ev_usd : 0; bv = b.farm_summary ? b.farm_summary.net_ev_usd : 0; }
      else { av = a.implied_value_usd; bv = b.implied_value_usd; }
      if (av < bv) return -state.dir;
      if (av > bv) return state.dir;
      return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
    });
  }

  function renderMasthead() {
    var v = DATA.validation || {};
    return el('header', { class: 'masthead' },
      el('div', { class: 'brand-group' },
        el('span', { class: 'radar-dot' }),
        el('span', { class: 'brand-title', text: 'LAUNCH RADAR' }),
        el('span', { class: 'brand-tag', text: DATA.model_version + ' · EMPIRICAL BAYES' })
      ),
      el('div', { class: 'meta-pills' },
        el('span', { class: 'meta-pill' }, 'Snapshot ', el('b', { text: DATA.as_of })),
        el('span', { class: 'meta-pill' }, 'Watchlist ', el('b', { text: DATA.watchlist_size + '/' + DATA.watchlist_size + ' (100%)' })),
        el('span', { class: 'meta-pill' }, 'LOO Error ', el('b', { text: 'x' + v.loo_median_error_x }), ' vs starter x' + v.starter_median_error_x),
        el('span', { class: 'meta-pill' }, 'Walk-Forward ', el('b', { text: 'x' + v.walk_forward_error_x })),
        el('span', { class: 'meta-pill' }, 'Odds Brier ', el('b', { text: String(v.brier_loo) }))
      )
    );
  }

  function renderHero() {
    var m = DATA.model;
    var v = DATA.validation || {};
    return el('section', { class: 'hero-grid' },
      el('div', { class: 'card' },
        el('h1', { class: 'hero-title', text: DATA.board_size + ' Pre-Token Protocols Priced by Empirical-Bayes Peer Multiples & Token Odds' }),
        el('p', { class: 'hero-sub', text: 'Covers all ' + DATA.watchlist_size + ' watchlist protocols (>=$' + Math.round(DATA.floor_usd / 1e6) + 'M TVL, no token on record) plus ' + DATA.early_size + ' early pre-token protocols below the floor. Live-token protocols (' + DATA.parity.live_token_protocols + ') are separated and used strictly to fit and cross-validate the valuation curve.' }),
        el('div', { class: 'formula-bar' },
          el('span', null, 'Model: ', el('code', { text: 'Implied = TVL * ' + m.base_multiple + ' * (TVL/$50M)^' + (m.beta_tvl - 1).toFixed(2) + ' * Cat_EB(K=' + m.shrinkage_k + ') * Growth_7d * Maturity * Chains' })),
          el('span', { class: 'sub', text: '0 hardcoded names · 100% deterministic' })
        )
      ),
      el('div', { class: 'card kpi-grid' },
        el('div', { class: 'kpi' },
          el('span', { class: 'kpi-label', text: 'LOO Held-Out' }),
          el('span', { class: 'kpi-val accent', text: 'x' + v.loo_median_error_x }),
          el('span', { class: 'kpi-note', text: 'n=' + v.live_priced_count + ' (starter x' + v.starter_median_error_x + ')' })
        ),
        el('div', { class: 'kpi' },
          el('span', { class: 'kpi-label', text: 'Walk-Forward' }),
          el('span', { class: 'kpi-val cobalt', text: 'x' + v.walk_forward_error_x }),
          el('span', { class: 'kpi-note', text: v.walk_forward_train_count + ' train -> ' + v.walk_forward_test_count + ' test' })
        ),
        el('div', { class: 'kpi' },
          el('span', { class: 'kpi-label', text: 'Token Odds Brier' }),
          el('span', { class: 'kpi-val accent', text: String(v.brier_loo) }),
          el('span', { class: 'kpi-note', text: 'vs base ' + v.brier_baseline + ' (n=' + v.eligible_count + ')' })
        ),
        el('div', { class: 'kpi' },
          el('span', { class: 'kpi-label', text: 'Placebo Null' }),
          el('span', { class: 'kpi-val', text: 'x' + v.placebo_error_x }),
          el('span', { class: 'kpi-note', text: 'permuted peer control' })
        )
      )
    );
  }

  function renderParityStrip() {
    var p = DATA.parity || {};
    return el('div', { class: 'parity-strip' },
      el('strong', { text: 'Universe Accounting (' + p.total_protocols + ' snapshot protocols):' }),
      el('div', { class: 'parity-items' },
        el('span', null, el('i', { class: 'p-dot p-wl' }), '40 Watchlist (>= $50M floor)'),
        el('span', null, el('i', { class: 'p-dot p-clean' }), p.early_clean_pre_token + ' Clean Early Pre-Token (< $50M)'),
        el('span', null, el('i', { class: 'p-dot p-eco' }), (DATA.board_size - DATA.watchlist_size - p.early_clean_pre_token) + ' Ecosystem Pre-Token Ranked'),
        el('span', null, el('i', { class: 'p-dot p-live' }), p.live_token_protocols + ' Live-Token Set Aside (Benchmarks)'),
        el('span', { class: 'sub', text: '+ ' + p.excluded_cex_or_versioned + ' CEX/Versioned excluded' })
      )
    );
  }

  function renderToolbar(currentList) {
    var categories = Array.from(new Set(DATA.rows.map(function (r) { return r.category || 'Other'; }))).sort();
    var chainCounts = {};
    DATA.rows.forEach(function (r) {
      (r.chains || []).forEach(function (c) { chainCounts[c] = (chainCounts[c] || 0) + 1; });
    });
    var topChains = Object.keys(chainCounts).sort(function (a, b) { return chainCounts[b] - chainCounts[a]; }).slice(0, 18);

    var search = el('input', {
      type: 'search',
      id: 'q',
      placeholder: 'Search protocol, slug, chain, verdict…',
      value: state.q,
      'aria-label': 'Search protocols'
    });
    search.addEventListener('input', function () { state.q = search.value; writeHash(); render(); });

    var catSelect = el('select', { id: 'category', 'aria-label': 'Filter by category' },
      el('option', { value: 'all', text: 'All Categories (' + categories.length + ')' }),
      categories.map(function (c) {
        return el('option', { value: c, text: c, selected: c === state.category ? 'selected' : null });
      })
    );
    catSelect.addEventListener('change', function () { state.category = catSelect.value; writeHash(); render(); });

    var chainSelect = el('select', { id: 'chain', 'aria-label': 'Filter by chain' },
      el('option', { value: 'all', text: 'All Chains' }),
      topChains.map(function (c) {
        return el('option', { value: c, text: c + ' (' + chainCounts[c] + ')', selected: c === state.chain ? 'selected' : null });
      })
    );
    chainSelect.addEventListener('change', function () { state.chain = chainSelect.value; writeHash(); render(); });

    var tierAll = el('button', { class: 'seg-btn', type: 'button', 'aria-pressed': state.tier === 'all' ? 'true' : 'false', text: 'All (' + DATA.board_size + ')', onclick: function () { state.tier = 'all'; writeHash(); render(); } });
    var tierWl = el('button', { class: 'seg-btn', type: 'button', 'aria-pressed': state.tier === 'watchlist' ? 'true' : 'false', text: 'Watchlist (' + DATA.watchlist_size + ')', onclick: function () { state.tier = 'watchlist'; writeHash(); render(); } });
    var tierEarly = el('button', { class: 'seg-btn', type: 'button', 'aria-pressed': state.tier === 'early' ? 'true' : 'false', text: 'Early <$50M (' + DATA.early_size + ')', onclick: function () { state.tier = 'early'; writeHash(); render(); } });

    var tabPre = el('button', { class: 'seg-btn', type: 'button', 'aria-pressed': state.tab === 'pre-token' ? 'true' : 'false', text: 'Pre-Token Radar', onclick: function () { state.tab = 'pre-token'; writeHash(); render(); } });
    var tabLive = el('button', { class: 'seg-btn', type: 'button', 'aria-pressed': state.tab === 'live' ? 'true' : 'false', text: 'Live Token Peers (' + DATA.live.length + ')', onclick: function () { state.tab = 'live'; writeHash(); render(); } });

    return el('div', { class: 'toolbar' },
      el('div', { class: 'field' }, el('label', { for: 'q', text: 'Search' }), search),
      el('div', { class: 'field' }, el('label', { for: 'category', text: 'Category' }), catSelect),
      el('div', { class: 'field' }, el('label', { for: 'chain', text: 'Chain' }), chainSelect),
      el('div', { class: 'field' }, el('span', { class: 'field-label', text: 'Cohort Slice' }), el('div', { class: 'seg-group' }, tierAll, tierWl, tierEarly)),
      el('div', { class: 'field' }, el('span', { class: 'field-label', text: 'Dataset View' }), el('div', { class: 'seg-group' }, tabPre, tabLive)),
      el('div', { class: 'toolbar-right' },
        el('span', { class: 'row-counter', text: state.tab === 'pre-token' ? currentList.length + ' / ' + DATA.board_size + ' rows' : DATA.live.length + ' live benchmarks' })
      )
    );
  }

  function renderFilterBanner(list) {
    var hasFilter = state.q.trim() !== '' || state.category !== 'all' || state.chain !== 'all' || state.tier !== 'all';
    if (!hasFilter || state.tab !== 'pre-token') return null;
    var totalTvl = list.reduce(function (s, r) { return s + r.tvl_usd; }, 0);
    var totalImp = list.reduce(function (s, r) { return s + r.implied_value_usd; }, 0);
    var avgOdds = list.length > 0 ? Math.round(list.reduce(function (s, r) { return s + (r.token_odds_pct || 50); }, 0) / list.length) : 0;

    var chips = [];
    if (state.category !== 'all') chips.push(el('span', { class: 'filter-chip', text: 'Category: ' + state.category }));
    if (state.chain !== 'all') chips.push(el('span', { class: 'filter-chip', text: 'Chain: ' + state.chain }));
    if (state.tier !== 'all') chips.push(el('span', { class: 'filter-chip', text: 'Cohort: ' + state.tier }));
    if (state.q.trim() !== '') chips.push(el('span', { class: 'filter-chip', text: 'Query: "' + state.q.trim() + '"' }));

    return el('div', { class: 'filter-banner' },
      el('div', { class: 'filter-tags' },
        el('strong', { text: 'Active Filter Slice:' }),
        chips
      ),
      el('div', { class: 'filter-stats' },
        list.length + ' matching protocols · Aggregate TVL ' + fmtUsd(totalTvl) + ' · Aggregate Implied ' + fmtUsd(totalImp) + ' · Mean Token Odds ' + avgOdds + '%'
      ),
      el('button', {
        class: 'reset-btn',
        type: 'button',
        text: 'Reset Filters',
        onclick: function () { state.q = ''; state.category = 'all'; state.chain = 'all'; state.tier = 'all'; writeHash(); render(); }
      })
    );
  }

  function sortTh(key, label, extraCls) {
    var active = state.sort === key;
    var arrow = active ? (state.dir < 0 ? ' ↓' : ' ↑') : '';
    return el('th', { scope: 'col', class: extraCls || null },
      el('button', {
        type: 'button',
        onclick: function () {
          if (state.sort === key) state.dir = -state.dir;
          else { state.sort = key; state.dir = -1; }
          render();
        }
      }, label + arrow)
    );
  }

  function fmtSignedUsd(n) {
    var v = Math.round(n || 0);
    return (v >= 0 ? '+$' : '-$') + Math.abs(v);
  }

  function verdictBadge(v) {
    var cls = v === 'STRONG FARM' ? 'verdict-strong' : v === 'POSITIVE EV' ? 'verdict-pos' : 'verdict-sel';
    return el('span', { class: 'verdict-chip ' + cls, text: v || 'POSITIVE EV' });
  }

  function renderBoardTable(list) {
    if (list.length === 0) {
      return el('div', { class: 'panel', style: 'padding: 36px; text-align: center;' },
        el('h2', { text: 'No pre-token protocol matches the active filter' }),
        el('p', { class: 'sub', style: 'margin: 8px 0 14px;', text: 'Reset the search query, category, or chain filter to restore the ranked board.' }),
        el('button', {
          class: 'reset-btn',
          type: 'button',
          text: 'Clear All Filters',
          onclick: function () { state.q = ''; state.category = 'all'; state.chain = 'all'; state.tier = 'all'; writeHash(); render(); }
        })
      );
    }
    var maxImp = list[0].implied_value_usd || 1;
    var tbody = el('tbody');
    list.forEach(function (r) {
      var growth = r.change_7d === null ? '0.00%' : fmtPct(r.change_7d);
      var growthCls = r.change_7d === null ? 'sub' : r.change_7d >= 0 ? 'pos' : 'neg';
      var tierLabel = r.on_watchlist ? 'WATCHLIST' : r.tier === 'early-clean' ? 'EARLY' : 'ECOSYSTEM';
      var tierCls = r.on_watchlist ? 'tier-wl' : r.tier === 'early-clean' ? 'tier-clean' : 'tier-eco';
      var fs = r.farm_summary || { recommended_capital_usd: 150, est_total_gas_usd: 10, hold_days: 30, net_ev_usd: 15, verdict: 'POSITIVE EV' };

      var tr = el('tr', {
        'data-selected': state.selected === r.slug ? 'true' : 'false',
        tabindex: '0',
        onclick: function () { selectProtocol(r.slug); },
        onkeydown: function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectProtocol(r.slug); } }
      },
        el('td', { class: 'num' }, el('span', { class: 'rank-badge', text: '#' + r.rank })),
        el('td', null,
          el('div', { class: 'proto-cell' },
            el('div', { class: 'proto-head' },
              el('span', { class: 'proto-name', text: r.name }),
              el('span', { class: 'tier-pill ' + tierCls, text: tierLabel })
            ),
            el('span', { class: 'sub', text: (r.category || 'Other') + ' · ' + (r.chains && r.chains.length ? r.chains.slice(0, 3).join(', ') + (r.chains.length > 3 ? ' +' + (r.chains.length - 3) : '') : 'Multi-chain') })
          )
        ),
        el('td', { class: 'num', text: fmtUsd(r.tvl_usd) }),
        el('td', { class: 'num ' + growthCls, text: growth }),
        el('td', { class: 'num hide-on-detail', text: fmtAgeShort(r.age_days) }),
        el('td', { class: 'num hide-on-detail' },
          el('span', { class: 'odds-pill', text: (r.token_odds_pct || 50) + '%' }),
          el('div', { class: 'sub', text: 'Pool ' + fmtUsd(r.airdrop_pool_usd) })
        ),
        el('td', null,
          el('div', { class: 'val-cell' },
            el('div', { class: 'val-top' },
              el('span', { class: 'num val-main', text: fmtUsd(r.implied_value_usd) }),
              el('span', { class: 'val-band', text: fmtUsd(r.implied_low_usd) + '–' + fmtUsd(r.implied_high_usd) })
            ),
            el('div', { class: 'bar', 'aria-hidden': 'true' },
              el('i', { style: 'width:' + Math.max(4, Math.min(100, Math.round((r.implied_value_usd / maxImp) * 100))) + '%' })
            )
          )
        ),
        el('td', null,
          verdictBadge(fs.verdict),
          el('div', { class: 'sub num', style: 'margin-top:2px;', text: '$' + fs.recommended_capital_usd + ' cap · ' + fs.hold_days + 'd · ' + fmtSignedUsd(fs.net_ev_usd) + ' EV' })
        )
      );
      tbody.appendChild(tr);
    });

    return el('div', { class: 'panel' },
      el('div', { class: 'table-wrap' },
        el('table', null,
          el('thead', null, el('tr', null,
            sortTh('implied', 'Rank'),
            sortTh('name', 'Protocol & Cohort'),
            sortTh('tvl', 'TVL'),
            sortTh('growth', '7d Δ'),
            sortTh('age', 'Tenure', 'hide-on-detail'),
            sortTh('odds', 'Token Odds', 'hide-on-detail'),
            sortTh('implied', 'Implied FDV (68% Band)'),
            sortTh('ev', 'Farm Verdict & Economics')
          )),
          tbody
        )
      )
    );
  }

  function renderLiveTable() {
    var tbody = el('tbody');
    DATA.live.forEach(function (r, idx) {
      var ratioStr = r.mcap_tvl_ratio !== null ? r.mcap_tvl_ratio.toFixed(2) + 'x' : 'n/a';
      tbody.appendChild(el('tr', null,
        el('td', { class: 'num' }, el('span', { class: 'rank-badge', text: 'L' + (idx + 1) })),
        el('td', null,
          el('div', { class: 'proto-cell' },
            el('div', { class: 'proto-head' },
              el('span', { class: 'proto-name', text: r.name }),
              r.symbol ? el('span', { class: 'tier-pill tier-clean', text: '$' + r.symbol }) : null
            ),
            el('span', { class: 'sub', text: (r.category || 'Other') + ' · ' + (r.chains && r.chains.length ? r.chains.slice(0, 3).join(', ') : 'Mainnet') })
          )
        ),
        el('td', { class: 'num', text: fmtUsd(r.tvl_usd) }),
        el('td', { class: 'num ' + (r.change_7d !== null && r.change_7d >= 0 ? 'pos' : 'neg'), text: fmtPct(r.change_7d) }),
        el('td', { class: 'num', style: 'font-weight:700;', text: fmtUsd(r.mcap_usd) }),
        el('td', { class: 'num', text: ratioStr }),
        el('td', { class: 'num', text: fmtUsd(r.model_pred_usd) }),
        el('td', null, el('span', { class: 'tier-pill tier-eco', text: 'ALREADY TRADES (BENCHMARK)' }))
      ));
    });
    return el('div', { class: 'panel' },
      el('div', { class: 'table-wrap' },
        el('table', null,
          el('thead', null, el('tr', null,
            el('th', { scope: 'col', text: '#' }),
            el('th', { scope: 'col', text: 'Live Protocol & Ticker' }),
            el('th', { scope: 'col', text: 'Snapshot TVL' }),
            el('th', { scope: 'col', text: '7d Δ' }),
            el('th', { scope: 'col', text: 'Actual Market Cap' }),
            el('th', { scope: 'col', text: 'MCap / TVL' }),
            el('th', { scope: 'col', text: 'Model Fit Pred' }),
            el('th', { scope: 'col', text: 'Role in Radar' })
          )),
          tbody
        )
      )
    );
  }

  function renderInspector(slug) {
    var row = DATA.rows.filter(function (r) { return r.slug === slug; })[0];
    if (!row) return null;
    var m = DATA.model;
    var recomputed = impliedOf(row, m);
    var matches = recomputed === row.implied_value_usd;
    var steps = farmStepsFor(row);
    var fs = row.farm_summary || { recommended_capital_usd: 150, est_total_gas_usd: 10, hold_days: 30, est_apr_equiv_pct: 25, net_ev_usd: 18, verdict: 'POSITIVE EV' };

    return el('aside', { class: 'inspector', id: 'detail', 'aria-labelledby': 'detail-title' },
      el('div', { class: 'insp-head' },
        el('div', null,
          el('div', { class: 'proto-head' },
            el('span', { class: 'brand-tag', text: 'RANK #' + row.rank + ' OF ' + DATA.board_size }),
            el('span', { class: 'tier-pill ' + (row.on_watchlist ? 'tier-wl' : 'tier-clean'), text: row.on_watchlist ? 'WATCHLIST FLOOR' : 'EARLY RADAR' }),
            verdictBadge(fs.verdict)
          ),
          el('h2', { class: 'insp-title', id: 'detail-title', text: row.name + ' (' + row.slug + ')' }),
          el('p', { class: 'sub', text: (row.category || 'Other') + ' · Active on ' + (row.chains && row.chains.length ? row.chains.join(', ') : 'Ethereum') })
        ),
        el('button', {
          class: 'close-btn',
          type: 'button',
          'aria-label': 'Close inspector',
          text: 'Close ×',
          onclick: function () { state.selected = null; writeHash(); render(); }
        })
      ),
      el('div', { class: 'insp-kpis' },
        el('div', { class: 'insp-box' },
          el('span', { text: 'Implied Value' }),
          el('b', { style: 'color:var(--accent);', text: fmtUsd(row.implied_value_usd) }),
          el('div', { class: 'sub num', text: 'Band ' + fmtUsd(row.implied_low_usd) + '–' + fmtUsd(row.implied_high_usd) })
        ),
        el('div', { class: 'insp-box' },
          el('span', { text: 'Token Launch Odds' }),
          el('b', { style: 'color:var(--cobalt);', text: (row.token_odds_pct || 50) + '% peer prob' }),
          el('div', { class: 'sub num', text: 'Est. 7% Airdrop ' + fmtUsd(row.airdrop_pool_usd) })
        ),
        el('div', { class: 'insp-box' },
          el('span', { text: 'Costed Farm Net EV' }),
          el('b', { text: fmtSignedUsd(fs.net_ev_usd) + ' (' + fs.est_apr_equiv_pct + '% APR)' }),
          el('div', { class: 'sub num', text: '$' + fs.recommended_capital_usd + ' cap · ~$' + fs.est_total_gas_usd + ' gas · ' + fs.hold_days + 'd' })
        )
      ),
      el('div', { class: 'insp-sec' },
        el('h3', { text: '1. Implied Valuation Decomposition (impliedOf verification)' }),
        el('div', { class: 'eq-grid' },
          el('div', { class: 'eq-row' }, el('span', { text: 'Snapshot TVL & Base Multiple (' + m.base_multiple + 'x @ $50M)' }), el('b', { text: fmtUsd(row.tvl_usd) + ' × ' + m.base_multiple })),
          el('div', { class: 'eq-row' }, el('span', { text: 'Concave TVL Scale (TVL / $50M)^(beta_tvl - 1)' }), el('b', { text: '× ' + row.tvl_scale_factor })),
          el('div', { class: 'eq-row' }, el('span', { text: 'Empirical Bayes Category Peer Multiple (' + (row.category || 'Other') + ')' }), el('b', { text: '× ' + row.category_multiplier })),
          el('div', { class: 'eq-row' }, el('span', { text: '7d TVL Momentum (' + fmtPct(row.change_7d) + ', clamped [-60%,+120%])' }), el('b', { text: '× ' + row.growth_multiplier })),
          el('div', { class: 'eq-row' }, el('span', { text: 'Tokenless Tenure (' + fmtAge(row.age_days) + ')' }), el('b', { text: '× ' + row.maturity_multiplier })),
          el('div', { class: 'eq-row' }, el('span', { text: 'Multi-Chain Footprint (' + (row.chains ? row.chains.length : 1) + ' chain' + (row.chains && row.chains.length === 1 ? '' : 's') + ')' }), el('b', { text: '× ' + row.chain_multiplier })),
          el('div', { class: 'eq-row total' },
            el('span', { text: 'Recomputed Page Value vs board.json' }),
            el('b', { text: fmtUsd(recomputed) + (matches ? ' ✓ Exact match ($' + row.implied_value_usd.toLocaleString('en-US') + ')' : ' (diff)') })
          )
        )
      ),
      el('div', { class: 'insp-sec' },
        el('h3', { text: '2. Concrete 6-Step Costed Farming Plan (' + chainOf(row) + ')' }),
        el('ol', { class: 'steps-list' },
          steps.map(function (st) {
            return el('li', null,
              el('b', { text: st.text }),
              el('span', { class: 'step-meta', text: 'Cost: ' + st.cost + ' · Time: ' + st.time })
            );
          })
        )
      )
    );
  }

  function renderBottomPanels() {
    var m = DATA.model;
    var v = DATA.validation || {};
    var cats = (DATA.categories || []).slice(0, 8);
    var catBody = el('tbody');
    cats.forEach(function (c) {
      catBody.appendChild(el('tr', {
        onclick: function () { state.category = c.category; state.tab = 'pre-token'; writeHash(); render(); }
      },
        el('td', { style: 'font-weight:600;', text: c.category }),
        el('td', { class: 'num', text: String(c.pre_token_count) }),
        el('td', { class: 'num', text: String(c.live_priced_count) }),
        el('td', { class: 'num pos', text: c.shrunk_multiple.toFixed(3) + 'x' }),
        el('td', { class: 'num', text: c.token_rate_pct + '%' }),
        el('td', { class: 'num', text: fmtUsd(c.total_tvl_usd) }),
        el('td', { class: 'num', style: 'font-weight:600;', text: fmtUsd(c.total_implied_usd) })
      ));
    });

    return el('section', { class: 'bottom-grid' },
      el('div', { class: 'panel', style: 'padding: 12px 16px;' },
        el('h3', { style: 'font-size:13.5px; margin-bottom:6px;', text: 'Empirical-Bayes Category Peer Multiples & Token Rates (Click a category to filter)' }),
        el('div', { class: 'table-wrap' },
          el('table', { class: 'mini-table' },
            el('thead', null, el('tr', null,
              el('th', { text: 'Category' }),
              el('th', { text: 'Pre-Tok' }),
              el('th', { text: 'Live Peers' }),
              el('th', { text: 'Shrunk MCap/TVL' }),
              el('th', { text: 'Peer Token Rate' }),
              el('th', { text: 'Pre-Tok TVL' }),
              el('th', { text: 'Implied Sum' })
            )),
            catBody
          )
        )
      ),
      el('div', { class: 'panel', style: 'padding: 12px 16px; display:grid; gap:8px; align-content:start;' },
        el('h3', { style: 'font-size:13.5px;', text: 'Methodology & Held-Out Verification Summary' }),
        el('p', { class: 'sub', style: 'line-height:1.45;', text: '1. Peer-Calibrated Concave Scaling: Across the ' + v.live_priced_count + ' live protocols with reported market cap, MCap scales sub-linearly with TVL (elasticity beta_tvl = ' + m.beta_tvl + ' around the $50M floor). Empirical Bayes shrinkage (K = ' + m.shrinkage_k + ') pulls sparse categories toward the universe median multiple (' + m.base_multiple + 'x).' }),
        el('p', { class: 'sub', style: 'line-height:1.45;', text: '2. Out-of-Sample Proof: Leave-one-out cross-validation achieves a median error factor of x' + v.loo_median_error_x + ' (improving substantially on the flat 0.25x starter baseline at x' + v.starter_median_error_x + ' and the permuted placebo control at x' + v.placebo_error_x + '). Chronological walk-forward (' + v.walk_forward_train_count + ' older protocols training -> ' + v.walk_forward_test_count + ' newest protocols testing) achieves x' + v.walk_forward_error_x + '.' }),
        el('p', { class: 'sub', style: 'line-height:1.45;', text: '3. Token Launch Odds & Costed Farm EV: Category token prevalence + operational tenure + multi-chain presence achieves a held-out LOO Brier score of ' + v.brier_loo + ' (vs ' + v.brier_baseline + ' uninformative prior) across ' + v.eligible_count + ' protocols, driving each row\'s net expected farm value.' })
      )
    );
  }

  function selectProtocol(slug) {
    state.selected = state.selected === slug ? null : slug;
    writeHash();
    render();
  }

  function render() {
    app.textContent = '';
    var list = sortedRows(filteredRows());
    var shell = el('div', { class: 'shell' });
    shell.appendChild(renderMasthead());
    shell.appendChild(renderHero());
    shell.appendChild(renderParityStrip());
    shell.appendChild(renderToolbar(list));
    var banner = renderFilterBanner(list);
    if (banner) shell.appendChild(banner);

    var inspectorNode = state.selected && state.tab === 'pre-token' ? renderInspector(state.selected) : null;
    var ws = el('div', { class: inspectorNode ? 'workspace with-detail' : 'workspace' });
    ws.appendChild(state.tab === 'pre-token' ? renderBoardTable(list) : renderLiveTable());
    if (inspectorNode) ws.appendChild(inspectorNode);
    shell.appendChild(ws);

    shell.appendChild(renderBottomPanels());
    app.appendChild(shell);
    app.setAttribute('aria-busy', 'false');
  }

  readHash();
  render();
  window.addEventListener('hashchange', function () {
    readHash();
    render();
  });
  window.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && state.selected) {
      state.selected = null;
      writeHash();
      render();
    }
  });
})();
